<?php
namespace App\Http\Controllers;
use App\Models\PersonnelType; use Illuminate\Http\{Request,RedirectResponse}; use Illuminate\Validation\Rule; use Illuminate\View\View;
class PersonnelTypeController extends Controller { public function index(Request $r): View { $f=$r->validate(['search'=>'nullable|string','status'=>['nullable',Rule::in(['active','inactive'])]]); $q=PersonnelType::query()->when($f['search']??null,fn($q,$s)=>$q->where('personnel_type','like',"%$s%"))->when(($f['status']??null)==='active',fn($q)=>$q->where('is_active',1))->when(($f['status']??null)==='inactive',fn($q)=>$q->where('is_active',0)); return view('personnel-types.index',['personnelTypes'=>$q->orderBy('personnel_type')->paginate(15)->withQueryString(),'filters'=>$f]); } public function create(): View { return view('personnel-types.create',['personnelType'=>new PersonnelType]); } public function store(Request $r): RedirectResponse { PersonnelType::create($this->rules($r)); return redirect()->route('personnel-types.index')->with('success','Personnel type created successfully.'); } public function edit(PersonnelType $personnelType): View { return view('personnel-types.edit',compact('personnelType')); } public function update(Request $r,PersonnelType $personnelType): RedirectResponse { $personnelType->update($this->rules($r,$personnelType)); return redirect()->route('personnel-types.index')->with('success','Personnel type updated successfully.'); } public function destroy(PersonnelType $personnelType): RedirectResponse { $personnelType->delete(); return back()->with('success','Personnel type deleted successfully.'); } private function rules(Request $r,?PersonnelType $p=null): array { return $r->validate(['personnel_type'=>['required','string','max:100',Rule::unique('personnel_types','personnel_type')->ignore($p)],'is_active'=>'required|boolean']); } }
